\begin{quote}
{Whenever $v_1,v_2,\ldots\in D(T)$ satisfy $v_n\xrightarrow{X}x$ and $Tv_n\xrightarrow{Y}y$ for some $x\in X$ and $y\in Y$, then $x\in D(T)$ and $Tx=y$.}
\end{quote}

\Needspace{6\baselineskip}
\begin{Proposition}\label{prop:closed-graph-domain-complete}
{An unbounded operator $T$ is closed if and only if its domain, endowed with the graph norm, is a Hilbert space.}
\end{Proposition}
